using Microsoft.AspNetCore.Components;
using MudBlazor;
using zxadocsfe.Helpers;
using zxadocsfe.Services;
using zxadocslib.Dtos;
using zxadocslib.Helpers;
using zxadocsui.State;

namespace zxadocsui.Components.Pages.Dashboard.Accounting;

/// <summary>
/// General ledger, trial balance, wallet ledger and journal report (ZD-255). The filters are shared;
/// each tab sends only the ones its report takes, and loads when opened. Excel and PDF exports
/// of the open tab are generated by the API with the same filters (ZD-339).
/// </summary>
public partial class AccountingReports
{
    private enum Tab { Ledger, TrialBalance, Wallet, Journals }

    [Inject] private IHttpService Http { get; set; } = default!;
    [Inject] private IPermissionClientService Permissions { get; set; } = default!;
    [Inject] private IUserSession Session { get; set; } = default!;
    [Inject] private ISnackbar Snackbar { get; set; } = default!;
    [Inject] private NavigationManager Nav { get; set; } = default!;

    private List<AccountingPeriodDto> periods = new();
    private List<GlAccountDto> accounts = new();
    private List<BillingUnitDto> units = new();
    private Tab tab;
    private int? periodId;
    private DateTime? from;
    private DateTime? to;
    private int? accountId;
    private int? unitId;
    private string? reference;
    private bool loading;

    private GeneralLedgerDto? ledger;
    private TrialBalanceDto? trialBalance;
    private WalletLedgerDto? wallet;
    private List<JournalDto>? journals;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        await Session.GetCurrentUser();
        if (!await Permissions.HasAny(Permission.ManageAccounting, Permission.ReverseJournal, Permission.ViewPettyCashFinance))
        {
            Snackbar.Add("You do not have access to accounting reports.", Severity.Warning);
            Nav.NavigateTo("/dashboard");
            return;
        }

        // Each list is gated on its own; a missing one only leaves its filter empty.
        periods = await Fetch<List<AccountingPeriodDto>>("api/accounting/periods") ?? new();
        accounts = await Fetch<List<GlAccountDto>>("api/accounting/accounts") ?? new();
        units = await Fetch<List<BillingUnitDto>>("api/petty-cash/billing-units") ?? new();
        await Load();
        StateHasChanged();
    }

    private void PickPeriod(int? id)
    {
        periodId = id;
        if (periods.FirstOrDefault(p => p.Id == id) is { } period)
            (from, to) = (period.StartDate.ToDateTime(TimeOnly.MinValue), period.EndDate.ToDateTime(TimeOnly.MinValue));
    }

    private async Task SwitchTab(int index)
    {
        tab = (Tab)index;
        await Load();
    }

    private async Task Load()
    {
        if (tab == Tab.Wallet && unitId is null)
        {
            wallet = null;
            Snackbar.Add("Choose a billing unit to see its wallet ledger.", Severity.Info);
            return;
        }

        loading = true;
        try
        {
            var suffix = Query();

            switch (tab)
            {
                case Tab.Ledger: ledger = await Fetch<GeneralLedgerDto>("api/accounting/reports/general-ledger" + suffix); break;
                case Tab.TrialBalance: trialBalance = await Fetch<TrialBalanceDto>("api/accounting/reports/trial-balance" + suffix); break;
                case Tab.Wallet: wallet = await Fetch<WalletLedgerDto>("api/accounting/reports/wallet-ledger" + suffix); break;
                default: journals = await Fetch<List<JournalDto>>("api/accounting/reports/journals" + suffix); break;
            }
        }
        finally
        {
            loading = false;
        }
    }

    /// <summary>The filters the current tab's report takes, as a query string; exports send exactly the same.</summary>
    private string Query()
    {
        var query = new List<string>();
        if (from is not null) query.Add($"from={from:yyyy-MM-dd}");
        if (to is not null) query.Add($"to={to:yyyy-MM-dd}");
        if (tab is Tab.Ledger or Tab.Journals)
        {
            if (accountId is not null) query.Add($"accountId={accountId}");
            if (!string.IsNullOrWhiteSpace(reference)) query.Add($"reference={Uri.EscapeDataString(reference.Trim())}");
        }
        if (tab != Tab.TrialBalance && unitId is not null) query.Add($"billingUnitId={unitId}");
        return query.Count > 0 ? "?" + string.Join("&", query) : "";
    }

    private string ReportName => tab switch
    {
        Tab.Ledger => "general-ledger",
        Tab.TrialBalance => "trial-balance",
        Tab.Wallet => "wallet-ledger",
        _ => "journals",
    };

    private async Task<T?> Fetch<T>(string url) where T : class
    {
        Http.Initialize(AppConstants.HttpSchemes.Core);
        var (ok, result, error) = await Http.GetAsync<ApiResponse<T>>(url);
        if (!ok && url.Contains("/reports/"))
            Snackbar.Add(ErrorMessage.Extract(error) ?? "Failed to load the report.", Severity.Error);
        return ok ? result?.Data : null;
    }

    private static string Amount(decimal value) => value == 0 ? "" : value.ToString("N2");
}
